import java.util.*;import java.lang.reflect.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;import com.google.gson.*;import io.github.r3neer.scalebrews.collision.api.*;import io.github.r3neer.scalebrews.collision.api.spi.*;import io.github.r3neer.scalebrews.collision.data.*;import io.github.r3neer.scalebrews.collision.geometry.*;import io.github.r3neer.scalebrews.collision.pose.*;import io.github.r3neer.scalebrews.collision.internal.*;import net.minecraft.resources.Identifier;import org.joml.Matrix4f;
public final class S60CatalogConsumer {
static int checks=0;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError("S60 CATALOG "+why);}static void bad(Runnable r){try{r.run();throw new AssertionError("S60 CATALOG invalid admitted");}catch(RuntimeException expected){checks++;}}
static List<AnatomyCatalogPayload> packets(WorldAnatomyCatalog c,UUID epoch)throws Exception{var m=WorldAnatomyCatalog.class.getDeclaredMethod("preparedPackets",UUID.class);m.setAccessible(true);return (List<AnatomyCatalogPayload>)m.invoke(c,epoch);}
static byte[] bytes(List<AnatomyCatalogPayload> p){var out=new java.io.ByteArrayOutputStream();for(var x:p)out.writeBytes(x.fragment());return out.toByteArray();}
static List<AnatomyCatalogPayload> frame(UUID epoch,long revision,JsonObject bundle)throws Exception{byte[] b=bundle.toString().getBytes(StandardCharsets.UTF_8);String digest=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));var out=new ArrayList<AnatomyCatalogPayload>();int count=(b.length+AnatomyCatalogPayload.CHUNK-1)/AnatomyCatalogPayload.CHUNK;for(int i=0;i<count;i++)out.add(new AnatomyCatalogPayload(epoch,AnatomyApi.PROTOCOL_VERSION,AnatomyApi.capabilities(),revision,i,count,b.length,digest,Arrays.copyOfRange(b,i*AnatomyCatalogPayload.CHUNK,Math.min(b.length,(i+1)*AnatomyCatalogPayload.CHUNK))));return out;}
static void accept(AnatomyCatalogTransfer t,List<AnatomyCatalogPayload> p){for(var packet:p){var b=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),net.minecraft.core.RegistryAccess.EMPTY);try{AnatomyCatalogPayload.CODEC.encode(b,packet);t.accept(AnatomyCatalogPayload.CODEC.decode(b));}finally{b.release();}}}

static CollisionBinding binding(String table,Set<String> channels){return new CollisionBinding(1,Identifier.parse("s60:actor"),Map.of(),new CollisionBinding.Geometry(Identifier.parse("s60:geometry"),Identifier.parse("s60:model"),Map.of(),new AnatomyFilter(0,0,0)),new CollisionBinding.Pose(Identifier.parse("scalebrews:finite_numeric_program"),Map.of("program",table),channels),Identifier.parse("s60:root"),CollisionPolicy.Patch.EMPTY,Set.of());}
public static void main(String[]args)throws Exception{
 BuiltInPoseEngines.initialize();CollisionEngines.registerGeometry(Identifier.parse("s60:geometry"),request->Optional.empty());CollisionEngines.registerRootTransform(Identifier.parse("s60:root"),e->Optional.empty());
 var gson=new Gson();var f=JsonParser.parseString(Files.readString(Path.of(args[0]))).getAsJsonArray().get(0).getAsJsonObject();var table=gson.fromJson(f.get("table"),FinitePoseProgram.class);String tableId=f.get("tableId").getAsString();var programs=new TreeMap<String,NumericPoseProgram>();f.getAsJsonObject("numericPrograms").entrySet().forEach(e->programs.put(e.getKey(),gson.fromJson(e.getValue(),NumericPoseProgram.class)));var model=programs.firstEntry().getValue().geometry();var required=new TreeSet<String>(table.booleans());for(var v:programs.values())for(var n:v.nodes())if(n.op()==NumericPoseProgram.Op.INPUT)required.add(n.input());var bindings=List.of(binding(tableId,required));var c=new WorldAnatomyCatalog();var snapshot=c.replace(Map.of("s60:model",model),Map.of(),Map.of(),programs,Map.of(tableId,table),bindings);var epoch=UUID.randomUUID();var packet=packets(c,epoch);var receiver=new AnatomyCatalogTransfer();accept(receiver,packet);check(receiver.ready()&&receiver.snapshot().finitePosePrograms().equals(snapshot.finitePosePrograms()),"finite wire ownership");var selected=receiver.snapshot().resolve(Identifier.parse("s60:actor"),Map.of()).orElseThrow();check(receiver.snapshot().bindingIdentity(selected).equals(snapshot.bindingIdentity(snapshot.resolve(Identifier.parse("s60:actor"),Map.of()).orElseThrow())),"binding ID wire");int matrices=0;var samples=JsonParser.parseString(Files.readString(Path.of(args[1]))).getAsJsonArray();
 for(int r=0;r<table.rows().size();r++)for(var e:samples.get(r).getAsJsonObject().getAsJsonArray("samples")){var o=e.getAsJsonObject();var channels=new TreeMap<String,Float>();o.getAsJsonObject("channels").entrySet().forEach(v->channels.put(v.getKey(),v.getValue().getAsFloat()));var actual=model.transforms(selected.poses().evaluate(new PoseEngine.Inputs(0,0,0,0,0,true,channels)).orElseThrow());for(var v:o.getAsJsonObject("matrices").entrySet()){check(actual.get(v.getKey()).equals(new Matrix4f().set(gson.fromJson(v.getValue(),float[].class)),3e-6f),"wire original matrix");matrices++;}}
 for(int i=0;i<100;i++)check(packets(c,epoch)==packet,"prepared packets rebuilt");var reversed=new LinkedHashMap<String,NumericPoseProgram>();programs.descendingMap().forEach(reversed::put);check(Arrays.equals(bytes(packet),bytes(AnatomyCatalogTransfer.encode(epoch,snapshot.revision(),Map.of("s60:model",model),Map.of(),Map.of(),reversed,Map.of(tableId,table),bindings))),"canonical insertion order");
 for(int mutation=0;mutation<6;mutation++){var raw=JsonParser.parseString(new String(bytes(packet),StandardCharsets.UTF_8)).getAsJsonObject();switch(mutation){case 0->raw.remove("finite_pose_programs");case 1->raw.getAsJsonObject("finite_pose_programs").getAsJsonObject(tableId).getAsJsonArray("rows").remove(table.rows().size()-1);case 2->raw.getAsJsonObject("finite_pose_programs").getAsJsonObject(tableId).getAsJsonArray("rows").get(table.rows().size()-1).getAsJsonObject().addProperty("program","s60:missing");case 3->raw.getAsJsonObject("finite_pose_programs").getAsJsonObject(tableId).getAsJsonArray("booleans").set(1,new JsonPrimitive(table.booleans().getFirst()));case 4->raw.getAsJsonObject("finite_pose_programs").getAsJsonObject(tableId).getAsJsonArray("rows").get(1).getAsJsonObject().addProperty("mask",0);case 5->raw.getAsJsonObject("finite_pose_programs").add("s60:"+"a".repeat(253),raw.getAsJsonObject("finite_pose_programs").get(tableId));}var prior=receiver.snapshot();var malformed=frame(epoch,receiver.revision()+1,raw);bad(()->accept(receiver,malformed));receiver.rejectPending();check(receiver.ready()&&receiver.snapshot()==prior,"finite rollback "+mutation);check(prior.resolve(Identifier.parse("s60:actor"),Map.of()).orElseThrow().poses()==selected.poses(),"rollback Bound identity");}
 var missing=new TreeMap<>(programs);missing.remove(table.rows().getLast().program());bad(()->c.replace(Map.of("s60:model",model),Map.of(),Map.of(),missing,Map.of(tableId,table),bindings));check(c.snapshot()==snapshot&&packets(c,epoch)==packet,"failed prepare rollback");var incomplete=new TreeSet<>(required);incomplete.remove(incomplete.last());bad(()->c.replace(Map.of("s60:model",model),Map.of(),Map.of(),programs,Map.of(tableId,table),List.of(binding(tableId,incomplete))));check(c.snapshot()==snapshot,"family schema rollback");
 var caps=new HashMap<String,FinitePoseProgram>();for(int i=0;i<4096;i++)caps.put("s60:table_"+i,table);c.replace(Map.of(),Map.of(),Map.of(),programs,caps,List.of());var capped=c.snapshot();caps.put("s60:overflow",table);bad(()->c.replace(Map.of(),Map.of(),Map.of(),programs,caps,List.of()));check(c.snapshot()==capped,"4097 table rollback");
 var opens=new int[1];String text=gson.toJson(table);var resource=new net.minecraft.server.packs.resources.Resource(null,()->{opens[0]++;return new java.io.ByteArrayInputStream(text.getBytes(StandardCharsets.UTF_8));});var files=new TreeMap<Identifier,net.minecraft.server.packs.resources.Resource>();files.put(Identifier.parse("s60:scalebrews/finite_pose_programs/one.json"),resource);var manager=(net.minecraft.server.packs.resources.ResourceManager)Proxy.newProxyInstance(S60CatalogConsumer.class.getClassLoader(),new Class[]{net.minecraft.server.packs.resources.ResourceManager.class},(object,method,arguments)->{if(method.getName().equals("listResources"))return files;throw new UnsupportedOperationException(method.getName());});var read=WorldAnatomyCatalog.class.getDeclaredMethod("readFinitePrograms",net.minecraft.server.packs.resources.ResourceManager.class,String.class);read.setAccessible(true);var loaded=(Map<?,?>)read.invoke(null,manager,"scalebrews/finite_pose_programs");check(loaded.get("s60:one").equals(table)&&opens[0]==1,"finite native resource reader");files.clear();for(int i=0;i<4097;i++)files.put(Identifier.parse("s60:scalebrews/finite_pose_programs/p"+i+".json"),resource);opens[0]=0;try{read.invoke(null,manager,"scalebrews/finite_pose_programs");throw new AssertionError("S60 CATALOG oversized files admitted");}catch(InvocationTargetException expected){check(expected.getCause() instanceof IllegalArgumentException,"wrong file cap exception");}check(opens[0]==0,"finite reader opened before cap");
 PoseEngine.Resources sam=id->Optional.empty();check(sam.finiteProgram(Identifier.parse("s60:x")).isEmpty(),"old Resources SAM");check(AnatomyApi.PROTOCOL_VERSION==8&&AnatomyApi.DATA_SCHEMA_VERSION==1&&!AnatomyApi.compatible(7,0)&&!AnatomyApi.compatible(8,Long.MIN_VALUE),"negotiation");Files.writeString(Path.of("accepted-bundle.json"),new String(bytes(packet),StandardCharsets.UTF_8));System.out.println("S60_CATALOG_PASS matrices="+matrices+" assertions="+checks+" malformedCandidates=6 rollback=true wireCodec=true cap4096/4097=true clientVeto=true");
}}
